package com.playsphere.turf;
import com.playsphere.common.Ids;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;
@Entity @Table(name="bookings") public class Booking{
 @Id @Column(length=36) private String id;@Column(name="booking_code",nullable=false,length=32) private String bookingCode;@Column(name="qr_token_hash",nullable=false,length=64) private String qrTokenHash;@Transient private String qrToken;@Column(name="player_user_id",nullable=false,length=36) private String playerUserId;@Column(name="turf_id",nullable=false,length=36) private String turfId;@Column(name="slot_id",nullable=false,length=36) private String slotId;@Column(nullable=false,precision=12,scale=2) private BigDecimal amount;@Column(nullable=false,length=24) private String status;@Column(name="payment_status",nullable=false,length=24) private String paymentStatus;@Column(name="cancellation_reason",length=400) private String cancellationReason;@Column(name="checked_in_at") private Instant checkedInAt;@Column(name="created_at",nullable=false) private Instant createdAt;@Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected Booking(){}public Booking(String player,TurfSlot slot,String hash,String raw){id=Ids.uuid();bookingCode=Ids.code("PS");qrTokenHash=hash;qrToken=raw;playerUserId=player;turfId=slot.getTurfId();slotId=slot.getId();amount=slot.getPrice();status="PENDING_PAYMENT";paymentStatus="PENDING";createdAt=updatedAt=Instant.now();}
 public String getId(){return id;}public String getBookingCode(){return bookingCode;}public String getQrToken(){return qrToken;}public String getPlayerUserId(){return playerUserId;}public String getTurfId(){return turfId;}public String getSlotId(){return slotId;}public BigDecimal getAmount(){return amount;}public String getStatus(){return status;}public String getPaymentStatus(){return paymentStatus;}public String getCancellationReason(){return cancellationReason;}public Instant getCheckedInAt(){return checkedInAt;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}
 public String getQrTokenHash(){return qrTokenHash;}public void rotateQr(String hash,String raw){qrTokenHash=hash;qrToken=raw;updatedAt=Instant.now();}public void paid(){paymentStatus="SUCCESS";status="CONFIRMED";updatedAt=Instant.now();}public void cancel(String reason){status="CANCELLED";cancellationReason=reason;updatedAt=Instant.now();}public void checkIn(){status="CHECKED_IN";checkedInAt=Instant.now();updatedAt=Instant.now();}
}
